import sys

def find_root(p):
    for i in range(len(p)):
        if p[i] == i:
            return i
    return -1

def is_valid_tree(p):
    visited = [False] * len(p)
    for i in range(len(p)):
        if visited[i]:
            continue
        current = i
        while not visited[current]:
            visited[current] = True
            current = p[current] - 1
        if current != i:
            return False
    return True

def minimum_changes_to_valid_tree(p):
    n = len(p)
    if is_valid_tree(p):
        return 0, p

    root = find_root(p)
    if root == -1:
        return -1, []

    changes = 0
    new_p = p[:]

    for i in range(n):
        if new_p[i] == i + 1:
            new_p[i] = root + 1
            changes += 1

    if is_valid_tree(new_p):
        return changes, new_p

    return -1, []

# Read input
n = int(sys.stdin.readline().strip())
p = list(map(int, sys.stdin.readline().strip().split()))

# Get the minimum number of changes and the valid sequence
changes, valid_sequence = minimum_changes_to_valid_tree(p)

# Output the result
print(changes)
print(*valid_sequence)
